function isIdentifier(char) {
    return (char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z') || char === '_';
}

function isNumber(char) {
    return char >= '0' && char <= '9';
}

function isOperator(char) {
    return char === '+' || char === '-' || char === '*' || char === '/';
}
